    --bg-color: #0a0a0a;
    --surface-color: #1a1a1a;
    --accent-color: #ffffff;
    --text-primary: #f5f5f5;
    --text-secondary: #a0a0a0;
    --border-color: #333333;
    --primary-btn-bg: #ffffff;
    --primary-btn-text: #000000;
    --container-width: 1200px;
    --transition: all 0.3s ease;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-primary);
    line-height: 1.6;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 2rem;
}

/* Header & Nav */
header {
    padding: 1.5rem 0;
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    background: rgba(10, 10, 10, 0.8);
    backdrop-filter: blur(10px);
    z-index: 1000;
}

nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 2px;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-links a {
    text-decoration: none;
    color: var(--text-secondary);
    font-weight: 500;
    font-size: 0.9rem;
    text-transform: uppercase;
    transition: var(--transition);
}

.nav-links a:hover {
    color: var(--text-primary);
}

.nav-icons {
    display: flex;
    gap: 1.5rem;
}

.nav-icons button {
    background: none;
    border: none;
    color: var(--text-primary);
    cursor: pointer;
    font-size: 1.2rem;
    position: relative;
}

#cart-count {
    position: absolute;
    top: -8px;
    right: -10px;
    background: var(--accent-color);
    color: var(--bg-color);
    font-size: 0.7rem;
    padding: 2px 5px;
    border-radius: 10px;
    font-weight: bold;
}

/* Hero Section */
.hero {
    height: 80vh;
    display: flex;
    align-items: center;
    background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), url('https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&q=80&w=1200') center/cover no-repeat;
    margin-bottom: 4rem;
}

.hero-content {
    max-width: 600px;
}

.badge {
    display: inline-block;
    padding: 0.5rem 1rem;
    background: var(--border-color);
    border-radius: 20px;
    font-size: 0.75rem;
    text-transform: uppercase;
    margin-bottom: 1rem;
}

.hero h1 {
    font-size: 4rem;
    line-height: 1.1;
    margin-bottom: 1.5rem;
}

.hero p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 1rem 2.5rem;
    text-decoration: none;
    font-weight: 600;
    border-radius: 4px;
    transition: var(--transition);
    cursor: pointer;
}

.btn-primary {
    background: var(--primary-btn-bg);
    color: var(--primary-btn-text);
}

.btn-primary:hover {
    background: var(--text-secondary);
}

.btn-outline {
    border: 1px solid var(--accent-color);
    color: var(--accent-color);
}

.btn-outline:hover {
    background: var(--accent-color);
    color: var(--bg-color);
}

/* Product Grid */
.section {
    padding: 4rem 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 2rem;
}

.view-all {
    color: var(--text-secondary);
    text-decoration: none;
    font-size: 0.9rem;
    border-bottom: 1px solid transparent;
}

.view-all:hover {
    border-bottom-color: var(--text-secondary);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background: var(--surface-color);
    border: 1px solid var(--border-color);
    padding: 1rem;
    transition: var(--transition);
}

.product-card:hover {
    transform: translateY(-5px);
    border-color: var(--text-secondary);
}

.product-image {
    width: 100%;
    aspect-ratio: 1/1;
    margin-bottom: 1.5rem;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.price {
    font-weight: 700;
    margin-bottom: 1.5rem;
}

.add-to-cart {
    width: 100%;
    padding: 0.8rem;
    background: transparent;
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    cursor: pointer;
    transition: var(--transition);
}

.add-to-cart:hover {
    background: var(--accent-color);
    color: var(--bg-color);
}

/* Deals Banner */
.deals-banner {
    background: var(--surface-color);
    padding: 6rem 0;
    margin: 4rem 0;
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
}

.deals-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 3rem;
    flex-wrap: wrap;
}

.deal-text h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.countdown {
    display: flex;
    gap: 2rem;
}

.time-unit {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.time-unit span {
    font-size: 2.5rem;
    font-weight: 800;
}

.time-unit label {
    font-size: 0.75rem;
    text-transform: uppercase;
    color: var(--text-secondary);
}

/* Footer */
footer {
    padding: 6rem 0 2rem;
    background: #000;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand p {
    margin-top: 1.5rem;
    color: var(--text-secondary);
    max-width: 300px;
}

.footer-links h4 {
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    font-size: 0.9rem;
    letter-spacing: 1px;
}

.footer-links ul {
    list-style: none;
}

.footer-links li {
    margin-bottom: 0.8rem;
}

.footer-links a {
    text-decoration: none;
    color: var(--text-secondary);
    transition: var(--transition);
}

.footer-links a:hover {
    color: var(--text-primary);
}

.footer-bottom {
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.8rem;
}

@media (max-width: 768px) {
    .nav-links {
        display: none;
    }

    .hero h1 {
        font-size: 3rem;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .deals-content {
        flex-direction: column;
        text-align: center;
    }
}
