    padding: 4rem 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 2rem;
}

.view-all {
    color: var(--text-secondary);
    text-decoration: none;
    font-size: 0.9rem;
    border-bottom: 1px solid transparent;
}

.view-all:hover {
    border-bottom-color: var(--text-secondary);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background: var(--surface-color);
    border: 1px solid var(--border-color);
    padding: 1rem;
    transition: var(--transition);
}

.product-card:hover {
    transform: translateY(-5px);
    border-color: var(--text-secondary);
}

.product-image {
    width: 100%;
    aspect-ratio: 1/1;
    margin-bottom: 1.5rem;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.price {
    font-weight: 700;
    margin-bottom: 1.5rem;
}

.add-to-cart {
    width: 100%;
    padding: 0.8rem;
    background: transparent;
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    cursor: pointer;
    transition: var(--transition);
}

.add-to-cart:hover {
    background: var(--accent-color);
    color: var(--bg-color);
}

/* Deals Banner */
.deals-banner {
    background: var(--surface-color);
    padding: 6rem 0;
    margin: 4rem 0;
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
}

.deals-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 3rem;
    flex-wrap: wrap;
}

.deal-text h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.countdown {
    display: flex;
    gap: 2rem;
}

.time-unit {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.time-unit span {
    font-size: 2.5rem;
    font-weight: 800;
}

.time-unit label {
    font-size: 0.75rem;
    text-transform: uppercase;
    color: var(--text-secondary);
}

/* Footer */
footer {
    padding: 6rem 0 2rem;
    background: #000;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand p {
    margin-top: 1.5rem;
    color: var(--text-secondary);
    max-width: 300px;
}

.footer-links h4 {
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    font-size: 0.9rem;
    letter-spacing: 1px;
}

.footer-links ul {
    list-style: none;
}

.footer-links li {
    margin-bottom: 0.8rem;
}

.footer-links a {
    text-decoration: none;
    color: var(--text-secondary);
    transition: var(--transition);
}

.footer-links a:hover {
    color: var(--text-primary);
}

.footer-bottom {
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.8rem;
}

@media (max-width: 768px) {
    .nav-links {
        display: none;
    }

    .hero h1 {
        font-size: 3rem;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .deals-content {
        flex-direction: column;
        text-align: center;
    }
}
